import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.BVA38fkC.js";var i=JSON.parse(`{"title":"Goal-Based Simulation — Implementation Plan","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/docs/strategies/goal-achievement-implementation-plan.html"}],["meta",{"property":"og:title","content":"Goal-Based Simulation — Implementation Plan | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/docs/strategies/goal-achievement-implementation-plan.html"}],["meta",{"name":"twitter:title","content":"Goal-Based Simulation — Implementation Plan | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"strategies/goal-achievement-implementation-plan.md","filePath":"strategies/goal-achievement-implementation-plan.md","lastUpdated":1793947830000}`),a={name:`strategies/goal-achievement-implementation-plan.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<blockquote><p><strong>Current status (2026-11-06): Goal mode is not user-selectable.</strong> The earlier implementation plan describes the previous multi-strategy goal direction. It is retained as implementation history only. The approved future architecture is Absolute R-only Goal optimisation; Greedy, GSS and Absolute R+ remain scoped. See <a href="./goal-mode-rework-plan.html">Goal-mode rework plan</a>.</p></blockquote><h1 id="goal-based-simulation-—-implementation-plan" tabindex="-1">Goal-Based Simulation — Implementation Plan <a class="header-anchor" href="#goal-based-simulation-—-implementation-plan" aria-label="Permalink to “Goal-Based Simulation — Implementation Plan”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>This document records the original shared goal-runtime implementation contract on <code>feature/goal-based-simulation</code>: accounting, runtime ownership, configuration migration, reporting and initial strategy integration. The later strategy-search follow-on is documented in <a href="./dual-scope-search-implementation-plan.html">Dual-Scope Search Strategies Implementation Plan</a>, which covers goal-aware GSS, Absolute and Absolute+ while preserving scoped-mode behaviour.</p><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to “Objective”">​</a></h2><p>Use two simulation modes: scoped date range and goal-driven execution. Goal mode terminates at the first event boundary where the configured amount of net interest credited to the consolidation account reaches its target. It has no user-configured end date; a 30-year internal safety horizon prevents non-terminating simulations.</p><p>The goal is not portfolio value, gross interest, unrealised FD interest, or total interest earned across all accounts. It is cumulative net interest actually credited to the configured consolidation account.</p><h2 id="configuration-contract" tabindex="-1">Configuration contract <a class="header-anchor" href="#configuration-contract" aria-label="Permalink to “Configuration contract”">​</a></h2><p>Canonical shape:</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;simulation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;goal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;goal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;metric&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;consolidation_net_interest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Modes:</p><ul><li><code>scoped</code>: explicit start and end dates.</li><li><code>goal</code>: start date and positive target; no user-defined end date. The engine applies a 30-year internal safety horizon.</li></ul><p>Legacy configurations remain valid through a single normalization layer. The CLI, browser configuration loader, and runtime must consume the same normalized contract. Existing investment date fields and strategy settings must remain backward compatible.</p><p>Validation must reject unsupported modes/metrics, non-positive or non-finite targets, invalid dates, internal safety horizons before the start date, missing mode-specific fields, and contradictory mode fields. Do not silently reinterpret malformed configurations.</p><h2 id="accounting-contract" tabindex="-1">Accounting contract <a class="header-anchor" href="#accounting-contract" aria-label="Permalink to “Accounting contract”">​</a></h2><h3 id="canonical-metric" tabindex="-1">Canonical metric <a class="header-anchor" href="#canonical-metric" aria-label="Permalink to “Canonical metric”">​</a></h3><p>Track a cumulative, first-credit-only amount of net interest credited to the consolidation account. Recognition occurs at the event boundary when the interest component is received by that account. AIT is deducted before recognition.</p><ul><li>Opening balances and external inflows are principal.</li><li>Principal returned at maturity is never interest.</li><li>Interest paid to a non-consolidation account is not counted until it reaches consolidation.</li><li>Interest moved between accounts is not counted more than once.</li><li>Reinvestment, withdrawals, and subsequent movement of already-counted interest do not reverse or duplicate the historical achievement metric.</li><li>Fees attributable to transferred interest reduce the net interest contribution.</li><li>Goal achievement is evaluated after all same-day credits, fees, transfers, and outflow settlement for the event boundary have been applied, with a deterministic event ordering documented and tested.</li></ul><h3 id="provenance-model" tabindex="-1">Provenance model <a class="header-anchor" href="#provenance-model" aria-label="Permalink to “Provenance model”">​</a></h3><p>Use explicit balance provenance (at minimum principal, uncredited net interest, and already-counted consolidation interest) in the shared runtime. Provenance must follow funds through transfers, bookings, maturity proceeds, and outflows.</p><p><strong>Mixed transfer policy:</strong> allocate a transfer and its fee proportionally across the source balance&#39;s principal and interest provenance. This is the deterministic default selected for implementation. Document the formula and cover rounding and residual-cent behaviour with tests. Principal remains principal; only net-interest provenance may contribute to the goal metric.</p><p>For each transfer, preserve source composition before mutation. Allocate gross transferred amount pro rata to each provenance bucket; allocate the transfer fee using the same proportions; subtract gross amount from source buckets and credit net amounts to target buckets. Apply a deterministic final-bucket residual so the component totals reconcile exactly to the monetary transfer and fee totals. Already-counted interest remains marked counted after transfer.</p><h3 id="fd-cash-flows" tabindex="-1">FD cash flows <a class="header-anchor" href="#fd-cash-flows" aria-label="Permalink to “FD cash flows”">​</a></h3><p>Cash-flow generation must expose principal and interest components, not just a single net amount. For cumulative payout, maturity returns principal plus net interest. Periodic payout emits net interest on interim dates and principal plus final-period net interest at maturity. Installment payout separates each installment&#39;s principal and net-interest portions. AIT is deducted from interest, not principal.</p><h2 id="runtime-lifecycle" tabindex="-1">Runtime lifecycle <a class="header-anchor" href="#runtime-lifecycle" aria-label="Permalink to “Runtime lifecycle”">​</a></h2><ul><li><code>SimulationRuntime</code> remains the sole authoritative event and money executor.</li><li><code>SimulationEngine</code> continues to own strategy-session orchestration and exactly-once finalization.</li><li>Goal termination is shared runtime/engine behaviour, never a strategy-specific stop implementation.</li><li>The runtime evaluates the canonical metric after each fully processed event boundary and records the first crossing.</li><li>The achieved run stops at that boundary; it must not process later events or run the final consolidation sweep at the internal safety-horizon boundary.</li><li>An unachieved run stops when no future events can advance it, or at the internal safety horizon, and returns a valid <code>goal_not_reached</code> outcome, distinct from invalid simulation or execution failure.</li><li>Finalization runs exactly once at the actual stopping boundary. Final sweep transfers must preserve provenance and must not retroactively change whether the goal was achieved.</li><li>Result metadata includes target, actual credited interest, achievement status, achievement date, elapsed days, overshoot or shortfall, safety-horizon boundary, and stopping reason.</li></ul><h2 id="strategy-compatibility-original-integration" tabindex="-1">Strategy compatibility (original integration) <a class="header-anchor" href="#strategy-compatibility-original-integration" aria-label="Permalink to “Strategy compatibility (original integration)”">​</a></h2><p>The following records the initial strategy integration at the time this plan was written. Current dual-scope search behaviour is maintained in the follow-on plan linked above.</p><ul><li>Greedy retains its existing local decision policy initially. It receives the shared runtime goal stop and serves as a baseline.</li><li>GSS initially retained its planning policy; the follow-on work adds provenance-aware goal plan ranking and recursive stopping.</li><li>Absolute+ initially used a goal-aware evaluator. The follow-on work adds provenance-aware beam/local ranking and goal-date-aware waiting. Rank candidates lexicographically: <ol><li>A goal-achieving candidate beats a non-achieving candidate.</li><li>Among achievers, earliest achievement date wins.</li><li>On the same date, higher net interest at achievement wins.</li><li>Then lower transfer fees and fewer unnecessary operations.</li><li>Then existing deterministic tie-breakers.</li></ol></li><li>Non-achieving candidates are ranked by net interest at the safety-horizon boundary, followed by existing tie-breakers.</li><li>Do not stop search at the first hypothetical crossing; compare candidates within the existing bounded search budget.</li><li>Keep beam width, local branch limit, decision cap, and existing strategy settings unchanged initially.</li><li>Expose search expansion/pruning diagnostics and state that bounded search does not prove global optimality unless a proof is actually available.</li></ul><h2 id="cash-outflow-handling" tabindex="-1">Cash-outflow handling <a class="header-anchor" href="#cash-outflow-handling" aria-label="Permalink to “Cash-outflow handling”">​</a></h2><p>Outflow settlement is a shared accounting concern, not a strategy-specific patch. When an outflow is paid, consume provenance deterministically and proportionally across the balance components. Preserve strict/defer/best-effort semantics and ensure unpaid obligations cannot silently disappear. Add regression coverage for outflows funded by principal, uncredited interest, and counted interest.</p><p>Until these tests pass, exclude outflow-heavy scenarios from primary strategy performance conclusions and document the limitation explicitly.</p><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to “Reporting”">​</a></h2><p>Goal-mode report sections, in this order:</p><ol><li><strong>Goal outcome</strong> — target, actual, achieved/not achieved, first achievement date, elapsed days, overshoot/shortfall, stopping reason.</li><li><strong>Achievement timeline</strong> — net-interest progression, target line, first crossing, relevant maturity and cash-flow events.</li><li><strong>Portfolio at achievement/stop</strong> — consolidation balance, cash, FD principal, realised net interest, AIT, transfer fees.</li><li><strong>Decision and performance analysis</strong> — decisions, transfers, bookings, strategy diagnostics, and Absolute+ search/pruning details.</li><li><strong>Scope status</strong> — achieved or safety-horizon boundary reached, with remaining shortfall.</li></ol><p>Do not present a fabricated achievement duration for an unachieved goal.</p><h2 id="goal-achievement-sensitivity-study" tabindex="-1">Goal achievement sensitivity study <a class="header-anchor" href="#goal-achievement-sensitivity-study" aria-label="Permalink to “Goal achievement sensitivity study”">​</a></h2><p>Add a separate study; preserve the existing fixed-horizon sensitivity benchmark. Use identical financial inputs and the same fixed 30-year internal safety horizon for Greedy, Absolute+, and GSS at each test point. Keep AIT, compounding, transfer fees, payout assumptions, and FD catalogues identical.</p><p>One-factor-at-a-time dimensions:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Values</th></tr></thead><tbody><tr><td>Goal target</td><td>LKR 10k, 25k, 50k, 75k, 100k</td></tr><tr><td>Starting capital</td><td>LKR 25k, 100k, 300k, 1m</td></tr><tr><td>Account count</td><td>1, 2, 3</td></tr><tr><td>Bank count</td><td>1, 2, 3</td></tr><tr><td>Inflows</td><td>none; monthly LKR 10k; quarterly LKR 30k; lump LKR 100k</td></tr><tr><td>eFD</td><td>standard-only; eligible</td></tr><tr><td>Internal safety horizon</td><td>Fixed at 30 years for all strategies and test points; not a user input</td></tr></tbody></table><p>Use DFCC, Commercial Bank, and NDB as the bank suite. Include achievable and deliberately difficult targets. Record achievement date, days to achievement, actual interest at achievement, target attainment, final net interest at the safety-horizon boundary, fees, bookings, runtime, Absolute+ expanded states, and proof status. For unachieved runs, report final net interest and shortfall, not an achievement duration. Exclude outflow scenarios from primary conclusions until outflow accounting is verified.</p><h2 id="migration-and-implementation-sequence" tabindex="-1">Migration and implementation sequence <a class="header-anchor" href="#migration-and-implementation-sequence" aria-label="Permalink to “Migration and implementation sequence”">​</a></h2><ol><li><p><strong>Inventory and baseline</strong></p><ul><li>Confirm branch base and enumerate all config entry points, event types, report adapters, CLI paths, web UI paths, strategy context construction, and tests.</li><li>Run the existing test suite before changes and record the baseline.</li><li>Identify all assumptions that currently require <code>investment.start_date</code> and <code>investment.end_date</code>.</li></ul></li><li><p><strong>Accounting primitives</strong></p><ul><li>Add principal/interest cash-flow component generation after AIT.</li><li>Add provenance balances and transfer/fee allocation.</li><li>Preserve provenance across FD booking and maturity.</li><li>Define outflow consumption and counted-interest permanence.</li><li>Add unit tests before integrating goal termination.</li></ul></li><li><p><strong>Simulation-mode normalization</strong></p><ul><li>Introduce the canonical mode object and one normalization function.</li><li>Preserve legacy scoped configurations; migrate legacy time-based browser drafts to scoped mode.</li><li>Update schema and semantic validation.</li><li>Add migration tests for legacy configs and both supported modes.</li></ul></li><li><p><strong>Shared runtime goal stop</strong></p><ul><li>Add canonical metric, threshold detection, first-crossing metadata, and stop reason to the shared runtime.</li><li>Integrate with engine orchestration and exactly-once finalization.</li><li>Test same-day ordering, overshoot, max-boundary failure-to-achieve, and no post-achievement event processing.</li></ul></li><li><p><strong>Strategy integration</strong></p><ul><li>Verify Greedy and GSS stop correctly without changing their decision policy.</li><li>Add goal-aware Absolute+ candidate evaluation and lexicographic ranking.</li><li>Test earliest achievement, tie-breaking, non-achievers, and search-budget exhaustion.</li></ul></li><li><p><strong>CLI and browser migration</strong></p><ul><li>Update CLI parsing/configuration and browser config form/schema together.</li><li>Add mode selector and mode-specific fields.</li><li>Keep financial settings and strategy settings intact.</li><li>Ensure exported/downloaded configs round-trip through the same normalizer.</li></ul></li><li><p><strong>Reports</strong></p><ul><li>Add goal-specific outcome, timeline, portfolio, and diagnostics.</li><li>Preserve existing fixed-horizon report output.</li><li>Verify achieved and unachieved report states.</li></ul></li><li><p><strong>Sensitivity runner and documentation</strong></p><ul><li>Add reproducible matrix runner and raw result JSON.</li><li>Generate charts from measured results only.</li><li>Document methodology, assumptions, limitations, and results.</li></ul></li><li><p><strong>Hardening and migration verification</strong></p><ul><li>Run all existing tests plus new accounting, mode, runtime, strategy, CLI, web, reporting, and benchmark tests.</li><li>Exercise target crossing, overshoot, unreachable goals, maturity boundaries, same-day events, inflows, multiple accounts/banks, final consolidation, and search-budget exhaustion.</li><li>Verify existing scoped output and settings remain unchanged.</li><li>Run browser build/deployment checks and inspect CI.</li><li>Fix every regression found and repeat the full suite before marking complete.</li></ul></li></ol><h2 id="acceptance-gates" tabindex="-1">Acceptance gates <a class="header-anchor" href="#acceptance-gates" aria-label="Permalink to “Acceptance gates”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> Legacy scoped configurations retain their existing semantics under regression tests.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> Both supported modes use one normalized configuration contract and one runtime.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> Canonical metric counts only first-time net interest credited to consolidation.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> AIT, principal, mixed transfers, fees, bookings, maturity, and outflow provenance reconcile under unit/integration coverage, including strict/defer/best-effort and multi-account isolation.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> Goal stops at the first valid event boundary and finalizes exactly once there.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> Unachieved goal is a valid explicit outcome with a shortfall.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> Greedy and GSS use shared stop semantics (goal lifecycle integration tests added).</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-7" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-7"> Absolute+ ranks achievers by earliest achievement within its bounded search; comparator, candidate replay, and bounded-search diagnostics are tested.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-8" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-8"> CLI, browser UI, schema, validation, and reports use the same mode contract; configuration normalization and browser-module syntax are covered.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-9" disabled="disabled"><label class="task-list-item-label" for="task-item-9"> Date-independent goal sensitivity matrix is rerun with the fixed 30-year internal safety horizon; the prior 72-run horizon-bounded artifact is superseded.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-10" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-10"> Outflow policy/provenance paths are covered by regression tests; outflows remain explicitly excluded from the primary sensitivity matrix.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-11" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-11"> Documentation, measured benchmark summary, and sensitivity charts describe the implemented behaviour.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-12" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-12"> Full regression suite, JavaScript syntax checks, documentation build, dependency review, and CodeQL pass on the latest implementation commit.</label></li></ul><h2 id="current-implementation-state-updated-6-november-2026" tabindex="-1">Current implementation state (updated 6 November 2026) <a class="header-anchor" href="#current-implementation-state-updated-6-november-2026" aria-label="Permalink to “Current implementation state (updated 6 November 2026)”">​</a></h2><h3 id="implemented-on-this-branch" tabindex="-1">Implemented on this branch <a class="header-anchor" href="#implemented-on-this-branch" aria-label="Permalink to “Implemented on this branch”">​</a></h3><ul><li>Added <code>simulation.mode</code> validation and normalization for scoped and goal-based horizons. Legacy configs without a mode remain scoped.</li><li>Added post-AIT cash-flow component generation for cumulative, periodic-interest, and installment products.</li><li>Added provenance buckets for principal, uncredited net interest, and previously counted interest.</li><li>Added proportional transfer/fee allocation, proportional outflow consumption, and provenance propagation through FD booking and maturity.</li><li>Added shared-runtime consolidation-credit recognition, first-crossing stop metadata, safety-horizon shortfall, and goal-aware final-sweep handling.</li><li>Added Greedy shared-runtime goal stopping and an Absolute+ goal candidate replay evaluator with lexicographic scoring, inherited runtime financial settings, invalid-candidate rejection, and bounded-search diagnostics.</li><li>Follow-on dual-scope strategy integration: GSS now uses provenance-aware recursive plan ranking and stops its hypothetical planner at the goal; Absolute uses exhaustive goal-specific search without scoped terminal-value/memo pruning; Absolute+ uses provenance-aware goal priority, local payout ranking and goal-date-aware waiting. Scoped financial outputs and search diagnostics were compared against the archived baseline and matched exactly for the recorded web-strategy matrices.</li><li>Migrated CLI and browser configuration inputs; added mode controls, export/import normalization, and goal summaries.</li><li>Added goal outcome and event-boundary progression to HTML and CLI reports.</li><li>Added a dedicated goal sensitivity runner and GitHub Actions workflow.</li><li>Added unit/integration tests for provenance, mixed transfers and fees, AIT component reconciliation, outflows, goal achievement, unreachable goals, final-sweep recognition, same-signal transfer/reinvestment, search evaluation, and report output.</li></ul><h3 id="verification-evidence" tabindex="-1">Verification evidence <a class="header-anchor" href="#verification-evidence" aria-label="Permalink to “Verification evidence”">​</a></h3><ul><li>The JavaScript test workflow, including browser/CLI syntax checks, passed on commit <code>cfb5ed1525d6bb8c77b5d7dfd7856793a32d7a15</code>, including candidate replay setting and invalid-path tests.</li><li>The general Node test workflow passed on commit <code>cfb5ed1525d6bb8c77b5d7dfd7856793a32d7a15</code>, including strict/defer/best-effort outflow policy and invalid-goal outcome tests.</li><li>The documentation build passed on commit <code>cfb5ed1525d6bb8c77b5d7dfd7856793a32d7a15</code>.</li><li>A reporting assertion exposed a missing CLI goal summary; that was fixed in commit <code>4aa21ad22d64de9f74784e29a971c52f9857ebbe</code>, whose JavaScript tests passed.</li><li>The earlier 72-run goal sensitivity matrix used 6-, 12-, and 24-month maximum scopes. It is superseded because goal mode no longer accepts a user-defined end date. The sensitivity runner now holds the 30-year internal safety horizon constant and removes horizon as a test dimension; the refreshed 63-run matrix is pending on this branch. The prior artifact <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42097850306" target="_blank" rel="noreferrer">42097850306</a> is retained as historical evidence only.</li><li>CodeQL passed on commit <code>cfb5ed1525d6bb8c77b5d7dfd7856793a32d7a15</code>.</li><li>The existing fixed-horizon strategy sensitivity and GAML search sensitivity workflow passed: <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42097833557" target="_blank" rel="noreferrer">run 42097833557</a>.</li><li>A clean pre-change baseline was not captured. Existing regression tests are used as compatibility gates instead.</li></ul><h3 id="remaining-work" tabindex="-1">Remaining work <a class="header-anchor" href="#remaining-work" aria-label="Permalink to “Remaining work”">​</a></h3><p>No required implementation or verification gates remain open. Outflow-heavy performance conclusions are intentionally excluded from the goal sensitivity matrix; a separate outflow sensitivity study can be added independently without blocking this feature.</p><p>The feature is implemented and verified. Keep the PR unmerged until review is complete.</p>`,53)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};